import sailpoint.object.*;
import sailpoint.api.*;
import sailpoint.workflow.*;
import java.util.*;
import org.apache.log4j.Logger;
import org.apache.log4j.Level;

Logger logger = Logger.getLogger("LCE.Joiner.Rule");
logger.setLevel(Level.INFO);

// LCE Input fields
String identityName  = null;
String firstName     = null;
String lastName      = null;
String email         = null;
String department    = null;
List applicationList = null;

// Workflow / Request objects
Workflow workflowObject      = null;
Identity requesterIdentity   = null;
String requesterId           = initiator;
long workflowLaunchTime      = 0L;
String workflowCaseName      = null;
Attributes workflowArgs      = new Attributes();
Attributes workflowInputArgs = null;
Request workflowRequest      = null;
RequestDefinition requestDef = null;

// Utility: Log application details
public void logApplications(Logger logger, Map lceInput) {
    if (lceInput == null) {
        logger.error("lceInput is null.");
        return;
    }
    Object appsObj = lceInput.get("applications");
    if (!(appsObj instanceof List)) {
        logger.error("applications is missing or not a List.");
        return;
    }
    List apps = (List) appsObj;
    logger.info("Applications Count: " + apps.size());
    for (int i = 0; i < apps.size(); i++) {
        Object appObj = apps.get(i);
        if (!(appObj instanceof Map)) {
            logger.warn("Skipping application index " + i + " (not a Map).");
            continue;
        }
        Map app = (Map) appObj;
        String appName   = (String) app.get("name");
        String operation = (String) app.get("operation");
        Map access       = (Map) app.get("access");
        logger.info("Application #" + i + ": " + appName + " | Operation=" + operation);
        if (access == null) {
            logger.info("  Access: none");
            continue;
        }
        List addAccess    = (List) access.get("add");
        List removeAccess = (List) access.get("remove");
        logger.info("  Add Access    : " + (addAccess != null ? addAccess : "[]"));
        logger.info("  Remove Access : " + (removeAccess != null ? removeAccess : "[]"));
    }
}

// Build provisioning plan
public ProvisioningPlan buildProvisioningPlan(Logger logger, List appList, Identity identity) {
    ProvisioningPlan plan = new ProvisioningPlan();
    plan.setIdentity(identity);
    if (appList == null || appList.isEmpty()) {
        logger.info("No dynamic applications found for provisioning.");
        return plan;
    }
    logger.info("Building provisioning plan for " + appList.size() + " applications.");
    for (int i = 0; i < appList.size(); i++) {
        Object appObj = appList.get(i);
        if (!(appObj instanceof Map)) {
            logger.warn("Skipping invalid application entry at index " + i);
            continue;
        }
        Map appMap = (Map) appObj;
        String appName   = (String) appMap.get("name");
        String operation = (String) appMap.get("operation");
        if (appName == null || operation == null) {
            logger.warn("Skipping app with missing name/operation at index " + i);
            continue;
        }
        logger.info("Building account request for: " + appName + " | Operation = " + operation);
        AccountRequest accReq = new AccountRequest();
        accReq.setApplication(appName);
        if ("Create".equalsIgnoreCase(operation)) {
            accReq.setOperation(AccountRequest.Operation.Create);
        } else if ("Modify".equalsIgnoreCase(operation)) {
            accReq.setOperation(AccountRequest.Operation.Modify);
        } else if ("Disable".equalsIgnoreCase(operation)) {
            accReq.setOperation(AccountRequest.Operation.Disable);
        } else if ("Delete".equalsIgnoreCase(operation)) {
            accReq.setOperation(AccountRequest.Operation.Delete);
        } else {
            logger.warn("Unknown operation for " + appName + ": " + operation);
            continue;
        }
        Map accessMap = (Map) appMap.get("access");
        if (accessMap != null) {
            List addList    = (List) accessMap.get("add");
            List removeList = (List) accessMap.get("remove");
            if (addList != null) {
                for (int a = 0; a < addList.size(); a++) {
                    String ent = (String) addList.get(a);
                    logger.info("   ADD entitlement: " + ent);
                    AttributeRequest attrReq = new AttributeRequest(
                        "entitlement",
                        ProvisioningPlan.Operation.Add,
                        ent
                    );
                    accReq.add(attrReq);
                }
            }
            if (removeList != null) {
                for (int r = 0; r < removeList.size(); r++) {
                    String ent = (String) removeList.get(r);
                    logger.info("   REMOVE entitlement: " + ent);
                    AttributeRequest attrReq = new AttributeRequest(
                        "entitlement",
                        ProvisioningPlan.Operation.Remove,
                        ent
                    );
                    accReq.add(attrReq);
                }
            }
        }
        plan.add(accReq);
    }
    return plan;
}

// Read LCE input
identityName  = (String) lceInput.get("identityName");
firstName     = (String) lceInput.get("firstName");
lastName      = (String) lceInput.get("lastName");
email         = (String) lceInput.get("email");
department    = (String) lceInput.get("department");
applicationList = (List) lceInput.get("applications");

logger.info("Processing Joiner for identity: " + identityName);

// Log application details and build plan
logApplications(logger, lceInput);
ProvisioningPlan provPlan = buildProvisioningPlan(logger, applicationList, context.getObjectByName(Identity.class, identityName));
logger.info("ProvisioningPlan built with " + provPlan.getAccountRequests().size() + " account requests.");

// Workflow lookup
workflowObject = context.getObject(Workflow.class, lceWorkflow);
if (workflowObject == null)
    throw new GeneralException("Workflow not found: " + lceWorkflow);

requesterIdentity = context.getObjectByName(Identity.class, requesterId);
if (requesterIdentity == null)
    requesterIdentity = context.getObjectByName(Identity.class, "spadmin");

// Build workflow request
workflowLaunchTime = System.currentTimeMillis() + 5000;
workflowCaseName = "Run '" + lceWorkflow + "' for " + identityName;
logger.info("Launching workflow: " + workflowCaseName);

workflowArgs = new Attributes();
workflowArgs.put("plan", provPlan);
workflowArgs.put("optimisticProvisioning", true);
workflowArgs.put("approvalScheme", "none");
workflowArgs.put("trace", false);
workflowArgs.put("notificationScheme", "none");
workflowArgs.put(StandardWorkflowHandler.ARG_REQUEST_DEFINITION, sailpoint.request.WorkflowRequestExecutor.DEFINITION_NAME);
workflowArgs.put(StandardWorkflowHandler.ARG_WORKFLOW, lceWorkflow);
workflowArgs.put(StandardWorkflowHandler.ARG_REQUEST_NAME, workflowCaseName);
workflowArgs.put("requestName", workflowCaseName);
workflowArgs.put("identityName", identityName);
workflowArgs.put("requestId", requestId);
workflowArgs.put("flow", eventType);
workflowArgs.put("launcher", initiator);
workflowArgs.put("lceData", lceData);

workflowRequest = new Request();
requestDef = context.getObject(RequestDefinition.class, "Workflow Request");
workflowRequest.setDefinition(requestDef);
workflowRequest.setOwner(requesterIdentity);
workflowRequest.setEventDate(new Date(workflowLaunchTime));
workflowRequest.setName(workflowCaseName);
workflowRequest.setAttributes(requestDef, workflowArgs);

RequestManager.addRequest(context, workflowRequest);

logger.info("Workflow request scheduled successfully.");

return true;

log.error("===lceData===="+lceInput);
log.error("===lceWorkflow===="+lceWorkflow);
log.error("===eventType===="+eventType);
log.error("===initiator===="+initiator);
log.error("===requestId===="+requestId);
return true;

log.error("===lceData===="+lceInput);
log.error("===lceWorkflow===="+lceWorkflow);
log.error("===eventType===="+eventType);
log.error("===initiator===="+initiator);
log.error("===requestId===="+requestId);
return true;
